const buildInstallments=(totalCents,downCents,count,firstDue)=>{if(count===1)return [{installment_no:1,due_date:firstDue,due_cents:totalCents}];const rest=totalCents-downCents;const regular=Math.floor(rest/(count-1));return Array.from({length:count},(_,index)=>({installment_no:index+1,due_date:addMonths(firstDue,index),due_cents:index===0?downCents:index===count-1?rest-regular*(count-2):regular}))};
