 const receive=async()=>{if(paid||receivingPayment)return;setReceivingPayment(true);try{if(backendStatus==='connected'){const accepted=await paymentApi.sandboxReceipt(tenant,'ui-demo-payment-v1');const payload=await paymentApi.overview(tenant);applyFinancialPayload(payload);setRepaymentOverview(await repaymentApi.overview(tenant));await refreshCatalog();setActivities(old=>old.map(a=>a.tenant===tenant&&a.caseIds.length===1&&a.caseIds[0]==='C002'?{...a,status:'completed',next:'本期已足额 · 下期 10.10',updated:'刚刚'}:a));addEvent('C002','本期补款已入账',`服务端 HMAC 验签、幂等、案件匹配、期次分摊与计佣完成；回执 ${accepted.receipt.id}`,'payment',{actor:'账务内核',tool:'payment.reconcile',version:'LEDGER v2',latency:'—',cost:'¥0.00'});setDialog(null);notify(accepted.duplicate?'该回执已处理，未重复入账':'服务端到账核验完成，期次、回款与佣金账簿已更新');return}setLedger(old=>[...old,{tenant_id:'TENANT_A',transaction_id:'DEMO-TX-001',case_id:'C002',package_id:'PKG_A',booked_date:'2026-09-12',event_type:'PAYMENT',cash_yuan:1016,eligible:true,eligible_cash_yuan:1016,rate:.15,commission_yuan:152.4,reason:'IN_MANDATE',commission_rule_id:'COM_A_V1',source:hostedDemo?'在线交互沙箱':'离线沙箱支付回调',signature:'沙箱验签通过',match_status:'已匹配',allocation:'PLAN002 · 第2期',idempotency:'首次接收'}]);setRepaymentOverview(old=>summarizeRepaymentPlans(old.plans.map(plan=>{if(plan.plan_id!=='PLAN002')return plan;const installments=plan.installments.map(row=>row.installment_no===2?{...row,paid_cents:row.due_cents,remaining_cents:0,status:'paid',last_payment_at:new Date().toISOString()}:row);const paid_cents=installments.reduce((sum,row)=>sum+row.paid_cents,0);return {...plan,installments,paid_cents,remaining_cents:plan.total_cents-paid_cents,overdue_cents:0}})));setPaid(true);setActivities(old=>old.map(a=>a.tenant==='TENANT_A'&&a.caseIds.length===1&&a.caseIds[0]==='C002'?{...a,status:'completed',next:'本期已足额 · 下期 10.10',updated:'10:48'}:a));addEvent('C002','本期补款已入账',`${hostedDemo?'在线':'离线'}演示完成验签、去重、匹配、期次分摊与计佣；未写入服务端账簿`,'payment',{actor:'演示账务接口',tool:'payment.reconcile',version:'DEMO v2',latency:'326 ms',cost:'¥0.00'});setDialog(null);notify(`${hostedDemo?'在线':'离线'}演示到账完成；未写入服务端账簿`)}catch(error){notify(`支付回执处理失败：${error.message}`)}finally{setReceivingPayment(false)}};
 const reconciliationCandidates=async receipt=>backendStatus==='connected'?paymentApi.matchCandidates(tenant,receipt.id):visibleCases.slice(0,5).map(c=>{const signed=['active','completed'].includes(c.governedPlan?.status)||c.plan?.status==='SIGNED';return {case_id:c.case_id,package_id:c.package_id,score:(signed?40:20)+(c.blocked?0:5),signals:['当前租户财务档案完整',signed?'存在已签履约方案':'无已签方案',c.blocked?'保护状态：仅允许被动到账核对':'案件未处于保护暂停'],blocked:c.blocked,has_signed_plan:signed}}).sort((x,y)=>y.score-x.score||x.case_id.localeCompare(y.case_id));
