 const decideReceiptReconciliation=async(review,decision,note)=>{if(identity.role!=='admin')throw new Error('仅管理员可以复核对账提案');if(review.proposed_by===identity.actor_id)throw new Error('提案人与复核人必须是不同账号');if(backendStatus==='connected'){const decided=await paymentApi.decideReconciliation(tenant,review.id,decision,note,review.version);applyFinancialPayload(await paymentApi.overview(tenant));notify(decision==='approve'?'复核已批准，回款与佣金账簿已原子更新':'复核已驳回，回执未进入钱指标');return decided}const receipt=financialOverview.pendingReceipts.find(row=>row.id===review.receipt_id);if(!receipt)throw new Error('待复核回执不存在');const reviewed={...review,status:decision==='approve'?'approved':'rejected',version:review.version+1,reviewed_by:identity.actor_id,reviewed_at:new Date().toISOString(),review_note:note,recovery_entry_id:decision==='approve'?`demo-review:${receipt.provider_event_id}`:null};if(decision==='approve'){const selected=visibleCases.find(c=>c.case_id===review.proposed_case_id);const rate=visiblePackages.find(p=>p.package_id===selected?.package_id)?.rate||0;const amount=receipt.amount_cents/100;const commission=Math.round(receipt.amount_cents*rate)/100;setLedger(old=>old.some(row=>row.transaction_id===reviewed.recovery_entry_id)?old:[...old,{tenant_id:tenant,transaction_id:reviewed.recovery_entry_id,receipt_id:receipt.id,case_id:review.proposed_case_id,package_id:selected?.package_id||'—',booked_date:receipt.occurred_at.slice(0,10),event_type:'PAYMENT',cash_yuan:amount,eligible:true,eligible_cash_yuan:amount,rate,commission_yuan:commission,reason:'IN_MANDATE',commission_rule_id:`DEMO-${selected?.package_id||'RULE'}`,source:'离线双人复核演示',signature:'HMAC v1 摘要已核验',match_status:'已匹配',allocation:`${review.proposed_case_id} · 人工复核匹配`,idempotency:'Provider 事件唯一'}]);addEvent(review.proposed_case_id,'人工对账复核已批准',`回执 ${receipt.provider_event_id} 通过双人复核；当前为浏览器演示事件`,'payment',{actor:identity.display_name,tool:'payment.reconciliation.approve',version:'RECON v1',cost:'¥0.00'})}setFinancialOverview(old=>{const summary=old.summary?{...old.summary,pending_receipt_count:Math.max(0,old.summary.pending_receipt_count-1)}:null;if(decision==='approve'&&summary){const rate=visiblePackages.find(p=>p.package_id===visibleCases.find(c=>c.case_id===review.proposed_case_id)?.package_id)?.rate||0;const commission=Math.round(receipt.amount_cents*rate);summary.confirmed_net_recovery_cents+=receipt.amount_cents;summary.commission_eligible_recovery_cents+=receipt.amount_cents;summary.accrued_commission_cents+=commission;summary.unsettled_commission_cents+=commission}return {...old,summary,pendingReceipts:old.pendingReceipts.filter(row=>row.id!==receipt.id),reconciliations:old.reconciliations.map(row=>row.id===review.id?reviewed:row)}});notify(decision==='approve'?'演示复核已批准；未写入服务端账簿':'演示复核已驳回；未更新钱指标');return reviewed};
 const proposeProtectionResolution=async(incident,note,evidenceRefs)=>{if(incident.release_policy==='permanent_hold')throw new Error('停止联系保护不能通过通用异常流程解除');if(backendStatus==='connected'){const proposed=await protectionApi.proposeResolution(tenant,incident.id,note,evidenceRefs);setProtectionOverview(await protectionApi.overview(tenant));notify('解除提案已提交，保护状态继续生效，等待独立管理员复核');return proposed}const refs=[...new Set(evidenceRefs.map(value=>value.trim().toUpperCase()).filter(Boolean))].sort();if(incident.release_policy==='renewal_evidence'&&!refs.some(value=>value.startsWith('MANDATE-')))throw new Error('委托到期保护需要 MANDATE- 开头的续期授权证据');const proposed={...incident,status:'pending_review',version:incident.version+1,resolution_note:note,evidence_refs:refs,evidence_digest:`demo-evidence-${Date.now()}`,proposed_by:identity.actor_id,proposed_at:new Date().toISOString(),reviewed_by:null,reviewed_at:null,review_note:null,case_released:false};setProtectionOverview(old=>summarizeProtection(old.incidents.map(row=>row.id===incident.id?proposed:row)));notify('演示解除提案已提交；保护状态仍然生效');return proposed};
 const decideProtectionResolution=async(incident,decision,note)=>{if(identity.role!=='admin')throw new Error('仅管理员可以复核保护解除提案');if(incident.proposed_by===identity.actor_id)throw new Error('提案人与复核人必须是不同账号');if(backendStatus==='connected'){const decided=await protectionApi.decideResolution(tenant,incident.id,decision,note,incident.version);setProtectionOverview(await protectionApi.overview(tenant));await refreshCatalog();if(decided.case_released)setExceptionResolutions(old=>({...old,[incident.case_id]:{status:'resolved',time:new Date().toISOString()}}));addEvent(incident.case_id,decision==='approve'?'保护解除提案已批准':'保护解除提案已驳回',decided.case_released?'案件进入待重新评估，原活动不会自动恢复':'案件继续保持保护暂停','exception',{actor:identity.display_name,tool:`protection.resolution.${decision}`,version:`GUARD v${decided.version}`});notify(decision==='approve'?(decided.case_released?'复核通过；案件已解除阻断并等待重新评估':'复核通过；案件仍有其他保护事件'):'复核已驳回；案件继续保持保护');return decided}const activeOthers=protectionOverview.incidents.some(row=>row.id!==incident.id&&row.case_id===incident.case_id&&protectionActiveStatuses.includes(row.status));const released=decision==='approve'&&!activeOthers;const decided={...incident,status:decision==='approve'?'resolved':'open',version:incident.version+1,reviewed_by:identity.actor_id,reviewed_at:new Date().toISOString(),review_note:note,resolved_at:decision==='approve'?new Date().toISOString():null,case_released:released};setProtectionOverview(old=>summarizeProtection(old.incidents.map(row=>row.id===incident.id?decided:row)));if(released)setExceptionResolutions(old=>({...old,[incident.case_id]:{status:'resolved',time:new Date().toISOString()}}));addEvent(incident.case_id,decision==='approve'?'保护解除提案已批准':'保护解除提案已驳回',released?'案件进入待重新评估；原活动不会自动恢复':'案件继续保持保护暂停','exception',{actor:identity.display_name,tool:`protection.resolution.${decision}`,version:`GUARD v${decided.version}`,cost:'¥0.00'});notify(decision==='approve'?(released?'演示复核通过；案件等待重新评估':'演示复核通过；仍有其他保护事件'):'演示复核驳回；保护继续生效');return decided};
 const proposeRepaymentPlan=async form=>{const selected=visibleCases.find(row=>row.case_id===form.caseId);if(!selected)throw new Error('案件不存在或不属于当前工作空间');const policy=getPolicy(selected.package_id);const claimCents=Math.round(selected.transfer_balance_yuan*100);const totalCents=Math.round(Number(form.total)*100);const downCents=Math.round(Number(form.down)*100);const count=Number(form.count);const agreementDigest=form.agreementDigest.trim().toLowerCase();if(!/^[0-9a-f]{64}$/.test(agreementDigest))throw new Error('请输入外部签约系统返回的 64 位 SHA-256 摘要');if(totalCents>claimCents)throw new Error('方案总额不能超过已核验债权余额');if(totalCents*100<claimCents*policy.minSettlement)throw new Error('方案总额低于当前资产包最低结算比例');if(downCents>totalCents||downCents*100<totalCents*policy.minDownPayment)throw new Error('首期金额不满足当前资产包最低首付比例');if(count<1||count>policy.maxInstallments)throw new Error('分期期数超过当前资产包策略上限');if(count===1&&downCents!==totalCents)throw new Error('单期方案的首期金额必须等于方案总额');const installments=buildInstallments(totalCents,downCents,count,form.firstDue);const planId=`PLAN-${form.caseId}-${Date.now().toString().slice(-8)}`;const payload={plan_id:planId,total_cents:totalCents,down_payment_cents:downCents,installments,agreement_reference:form.agreementReference.trim().toUpperCase(),agreement_digest:agreementDigest,signed_at:new Date().toISOString(),proposal_reason:form.reason.trim()};if(backendStatus==='connected'){const plan=await repaymentApi.propose(tenant,form.caseId,payload);setRepaymentOverview(await repaymentApi.overview(tenant));notify('签约方案已提交；批准前不会改变案件或期次余额');return plan}const plan={id:`DEMO-RPLAN-${Date.now()}`,...payload,case_id:form.caseId,status:'pending_review',version:1,currency:'CNY',claim_balance_cents:claimCents,installment_count:count,policy_version:policy.version,policy_snapshot:{min_settlement_bps:policy.minSettlement*100,max_installments:policy.maxInstallments,min_down_payment_bps:policy.minDownPayment*100},evidence_digest:agreementDigest,proposal_reason:payload.proposal_reason,proposed_by:identity.actor_id,proposed_at:new Date().toISOString(),reviewed_by:null,reviewed_at:null,review_note:null,activated_at:null,completed_at:null,paid_cents:0,remaining_cents:totalCents,overdue_cents:0,installments:installments.map(row=>({...row,installment_id:`${planId}-${String(row.installment_no).padStart(2,'0')}`,paid_cents:0,remaining_cents:row.due_cents,status:'scheduled',last_payment_at:null}))};setRepaymentOverview(old=>summarizeRepaymentPlans([plan,...old.plans]));notify('演示签约提案已提交；未写入服务端');return plan};
 const decideRepaymentPlan=async(plan,decision,note)=>{if(identity.role!=='admin')throw new Error('仅管理员可以复核签约方案');if(plan.proposed_by===identity.actor_id)throw new Error('提案人与复核人必须是不同账号');if(backendStatus==='connected'){const decided=await repaymentApi.decide(tenant,plan.id,decision,note,plan.version);setRepaymentOverview(await repaymentApi.overview(tenant));await refreshCatalog();addEvent(plan.case_id,decision==='approve'?'签约方案已激活':'签约方案已驳回',decision==='approve'?'签署摘要和条款通过独立复核；等待验签回款分摊':'方案未生效，案件状态和资金事实未改变','plan',{actor:identity.display_name,tool:`repayment_plan.${decision}`,version:`PLAN v${decided.version}`,cost:'¥0.00'});notify(decision==='approve'?'方案已激活；仅验签回款能够减少期次余额':'方案已驳回；案件和资金状态未改变');return decided}const decided={...plan,status:decision==='approve'?'active':'rejected',version:plan.version+1,reviewed_by:identity.actor_id,reviewed_at:new Date().toISOString(),review_note:note,activated_at:decision==='approve'?new Date().toISOString():null};setRepaymentOverview(old=>summarizeRepaymentPlans(old.plans.map(row=>row.id===plan.id?decided:row)));notify(decision==='approve'?'演示方案已激活；未写入服务端':'演示方案已驳回');return decided};
 const switchTenant=id=>{setTenant(id);setScope('all');setCaseId(null);setCaseDetail(null);setDialog(null);setWorkspaceOpen(false);navigate('activities');notify(`已切换至${organization[id]}`)};
