 const refreshAgentGateway=async()=>{const gateway=await agentApi.gateway(tenant);setAgentGateway(gateway);agentSessions.current=Object.fromEntries(Object.entries(agentSessions.current).filter(([key])=>!key.startsWith(`${tenant}:`)));return gateway};
 const refreshModelGateway=async()=>{const health=await securityApi.modelGatewayHealth(tenant);setModelGateway(health);return health};
 const saveServiceConfig=async(service,config)=>{if(backendStatus!=='connected'){updateServiceConfig(service,{...config,saved:true,tested:false,latency:'—'});if(service==='agent'){setAgentGateway(current=>({...current,provider:config.provider,profile:config.profile,transport:config.transport||'sandbox-contract',session_persistence:config.sessionPersistence||'database-checkpoint',connected:false}));agentSessions.current=Object.fromEntries(Object.entries(agentSessions.current).filter(([key])=>!key.startsWith(`${tenant}:`)))}return null}const payload=await integrationApi.save(tenant,service,config);const normalized=applyRemoteOverview(payload);if(service==='agent')await refreshAgentGateway();if(service==='model')await refreshModelGateway();return normalized};
 const testServiceConnection=async(service,config)=>{if(backendStatus!=='connected'){const latency=service==='agent'?'126 ms':service==='model'?'72 ms':service==='voice'?'236 ms':'41 ms';updateServiceConfig(service,{...config,saved:true,tested:true,latency});if(service==='agent'){setAgentGateway(current=>({...current,provider:config.provider,profile:config.profile,transport:config.transport||'sandbox-contract',session_persistence:config.sessionPersistence||'database-checkpoint',connected:true}));agentSessions.current=Object.fromEntries(Object.entries(agentSessions.current).filter(([key])=>!key.startsWith(`${tenant}:`)))}return null}await integrationApi.save(tenant,service,config);await integrationApi.test(tenant,service,setActiveJob);const normalized=applyRemoteOverview(await integrationApi.get(tenant));if(service==='agent')await refreshAgentGateway();if(service==='model')await refreshModelGateway();return normalized};
 const runIntegrationSelfTest=async()=>{if(backendStatus!=='connected')return null;await integrationApi.selfTest(tenant,setActiveJob);return applyRemoteOverview(await integrationApi.get(tenant)).state.lastRun};
 const enableIntegration=async()=>{if(backendStatus!=='connected'){updateIntegrationState({enabled:true,enabledAt:formatNow(),enabledBy:'Terry',enabledServiceVersions:serviceVersionSnapshot(serviceConfigs),invalidatedReason:null});return null}return applyRemoteOverview(await integrationApi.enable(tenant))};
 const preflightActivity=async form=>backendStatus==='connected'?activityApi.preflight(tenant,form):null;
 const askAgent=async(content,scope={})=>{if(backendStatus!=='connected')return null;const scopeType=scope.scopeType||'global';const scopeId=scope.scopeId||null;const key=`${tenant}:${scopeType}:${scopeId||'root'}`;let sessionId=agentSessions.current[key];if(!sessionId){const session=await agentApi.createSession(tenant,{scopeType,scopeId,title:scope.title||`${PRODUCT_NAME} 会话`});sessionId=session.id;agentSessions.current[key]=sessionId}const job=await agentApi.message(tenant,sessionId,content,setActiveJob);return {...job.result,session_id:sessionId}};
 const confirmAgentProposal=async proposalId=>{if(backendStatus!=='connected')return null;const result=await agentApi.confirmProposal(tenant,proposalId);return result};
 const runModelReplay=async(mode='deterministic-contract')=>{if(backendStatus!=='connected')return null;const job=await agentApi.replay(tenant,mode,setActiveJob);const replay=await agentApi.replayRun(tenant,job.result.replay_run_id);setLatestReplay(replay);return replay};
 const queueLabel=backendStatus==='auth-required'?'需要企业身份':backendStatus==='api-error'?'API 配置异常':backendStatus!=='connected'?(hostedDemo?'在线演示 · API 未接入':'离线演示 · 本地运行'):queueHealth.mode==='external'?(queueHealth.status==='healthy'?'独立 Worker · 持久运行':'Worker 降级 · 作业保留'):'API 内联 · 持久作业';
 const a={tenant,theme,setTheme,route,page,navigate,activities,visibleActivities,cases,visibleCases,packages,visiblePackages,catalogTotals,catalogRevision,refreshCatalog,ledger,visibleLedger,events,paid,receivingPayment,financialOverview,protectionOverview,repaymentOverview,scope,setScope,dialog,setDialog,openCase,notify,setActivityStatus,getPolicy,savePolicy,runSteps,advance,receive,reconciliationCandidates,createReconciliationSample,proposeReceiptReconciliation,decideReceiptReconciliation,proposeProtectionResolution,decideProtectionResolution,proposeRepaymentPlan,decideRepaymentPlan,createActivity,preflightActivity,organization,setOrganization,notificationPreferences,setNotificationPreferences,serviceConfigs,integrationState,integrationReadiness,backendStatus,hostedDemo,identity,agentGateway,modelGateway,queueHealth,secretHealth,authHealth,latestReplay,activeJob,askAgent,confirmAgentProposal,runModelReplay,updateServiceConfig,updateIntegrationState,saveServiceConfig,testServiceConnection,runIntegrationSelfTest,enableIntegration,reset,copilotOpen,setCopilotOpen,exceptionResolutions,setExceptionResolutions,addEvent};
 const activeCaseBase=caseDetail?.case_id===caseId?caseDetail:visibleCases.find(c=>c.case_id===caseId);
 const activeCase=activeCaseBase?{...activeCaseBase,governedPlan:repaymentOverview.plans.find(plan=>plan.case_id===activeCaseBase.case_id&&['pending_review','active','completed'].includes(plan.status))}:null;
 const activeRepaymentPlan=dialog?.type==='plan-review'?repaymentOverview.plans.find(plan=>plan.id===dialog.planId):null;
 const results=search.trim()?visibleCases.filter(c=>(c.case_id+' '+c.package_id+' '+c.status).toLowerCase().includes(search.toLowerCase())).slice(0,5):[];
 const acts=search.trim()?visibleActivities.filter(x=>(x.name+x.id).toLowerCase().includes(search.toLowerCase())).slice(0,3):[];
 if(backendStatus==='auth-required'||backendStatus==='api-error')return <main className="startup-blocked"><section><ShieldCheck size={34}/><span className="eyebrow">REPAYGUARD STARTUP GATE</span><h1>{backendStatus==='auth-required'?'需要企业身份':'业务 API 尚未就绪'}</h1><p>{backendStatus==='auth-required'?'API 已响应，但当前会话没有有效身份或工作空间权限。系统不会把认证失败降级成可写的本地演示。':backendError}</p><div className="notice">请完成企业 SSO 登录或修复服务端配置后重新加载。当前未执行任何业务写入。</div><div className="footer-actions">{backendStatus==='auth-required'&&oidcConfigured()&&<Button variant="primary" onClick={()=>beginOidcLogin().catch(error=>setBackendError(error.message))}>企业 SSO 登录</Button>}<Button onClick={()=>window.location.reload()}>重新检查</Button></div></section></main>;
 return <AppContext.Provider value={a}><div className={`app-shell ${mobileOpen?'mobile-open':''}`}>
 <aside className="sidebar"><button className="brand" onClick={()=>navigate('overview')}><img src={BRAND_ASSET} alt={`${PRODUCT_NAME} 标志`}/><span><strong>{PRODUCT_NAME}</strong><small>{PRODUCT_ENGLISH_NAME} · {PRODUCT_DESCRIPTOR}</small></span></button>
 <div className="workspace-area"><button className="workspace-switch" aria-expanded={workspaceOpen} onClick={()=>setWorkspaceOpen(!workspaceOpen)}><Buildings size={21}/><span><b>{organization[tenant]}</b><small>资产履约工作空间</small></span><CaretDown size={14}/></button>{workspaceOpen&&<div className="workspace-pop"><span className="overline">切换工作空间</span>{['TENANT_A','TENANT_B'].map(id=><button key={id} onClick={()=>switchTenant(id)}><Buildings size={17}/>{organization[id]}{tenant===id&&<CheckCircle size={17}/>}</button>)}</div>}</div>
 <button className="sidebar-search" onClick={()=>{setSearch('');setNotificationOpen(false);setSearchOpen(true)}}><MagnifyingGlass size={18}/><span>快速搜索</span><kbd>⌘ K</kbd></button>
 <nav>{nav.map(([id,Icon])=><React.Fragment key={id}>{id==='agents'&&<div className="nav-label">AI 运营</div>}<button className={page===id?'nav-item active':'nav-item'} aria-current={page===id?'page':undefined} onClick={()=>navigate(id)}><Icon size={20}/><span>{titles[id]}</span>{id==='activities'&&<small>{visibleActivities.filter(x=>x.status==='running').length}</small>}{id==='plans'&&repaymentOverview.pending_review_count>0&&<small>{repaymentOverview.pending_review_count}</small>}{id==='exceptions'&&protectedCount>0&&<small>{protectedCount}</small>}</button></React.Fragment>)}</nav>
 <div className="sidebar-bottom"><div className="simulation-status"><span className={backendStatus==='connected'&&queueHealth.status==='degraded'?'warning-dot':'live-dot'}/>{queueLabel}</div><button className={`nav-item ${page==='usage'?'active':''}`} onClick={()=>navigate('usage')}><Receipt size={20}/>用量与账单</button><button className={`nav-item ${page==='settings'?'active':''}`} onClick={()=>navigate('settings')}><GearSix size={20}/>组织设置</button><div className="profile"><span className="avatar">{identity.display_name?.slice(0,1)||'T'}</span><span>{identity.display_name}<small>{identity.role==='admin'?'工作空间管理员':identity.role==='operator'?'运营人员':'观察员'} · {identity.auth_mode==='oidc'?'OIDC':'开发身份'}</small></span><span className="plan-tag">Team</span></div></div></aside>
 <div className="main-shell"><header className="topbar"><IconButton icon={List} label="打开导航" className="mobile-menu icon-btn" onClick={()=>setMobileOpen(!mobileOpen)}/><div className="breadcrumb"><span>工作空间</span><span>/</span><b>{titles[page]||'履约活动'}</b>{route.includes('/')&&<><span>/</span><span>运行详情</span></>}</div><div className="top-actions"><button className="global-search mobile-search" onClick={()=>{setSearch('');setNotificationOpen(false);setSearchOpen(true)}}><MagnifyingGlass size={17}/><span>搜索案件、活动或功能…</span><kbd>⌘ K</kbd></button><button className="top-ai-button" onClick={()=>setCopilotOpen(true)}><Robot size={16}/><span>AI 查询</span><kbd>⌘ J</kbd></button><span className={`demo-tag ${backendStatus==='connected'?'server-connected':''}`}>{backendStatus==='connected'?`API v${APP_VERSION}`:hostedDemo?'在线演示':'演示'}</span><div className="notification-wrap"><button className="icon-btn notification-trigger" aria-label="打开通知中心" aria-expanded={notificationOpen} onClick={()=>setNotificationOpen(!notificationOpen)}><Bell size={19}/>{!notificationsRead&&<span className="notification-count">3</span>}</button>{notificationOpen&&<section className="notification-pop" aria-label="通知中心"><header><div><b>通知中心</b><small>AI 运行与账务提醒</small></div><button className="text-link small" onClick={()=>setNotificationsRead(true)}>全部已读</button></header><button onClick={()=>navigate('exceptions')}><span className="notification-icon warning"><ShieldCheck size={18}/></span><span><b>{protectedCount} 个案件已保护暂停</b><small>争议、停止联系或授权异常已阻断触达</small></span></button><button onClick={()=>navigate('plans')}><span className="notification-icon"><CalendarCheck size={18}/></span><span><b>{repaymentOverview.pending_review_count} 个签约方案等待复核</b><small>独立批准后才进入履约，回款才减少期次余额</small></span></button><button onClick={()=>navigate('payments')}><span className="notification-icon"><CurrencyCircleDollar size={18}/></span><span><b>{financialOverview.summary?.pending_receipt_count||0} 笔回执等待复核</b><small>核验后才会更新履约与应计佣金</small></span></button></section>}</div><IconButton icon={theme==='light'?Moon:Sun} label={theme==='light'?'切换深色主题':'切换浅色主题'} onClick={()=>setTheme(theme==='light'?'dark':'light')}/><IconButton icon={Question} label="交互指南" onClick={()=>setDialog({type:'help'})}/><button className="avatar top-avatar" aria-label="打开个人设置" onClick={()=>identity.auth_mode==='oidc'?logoutOidc():navigate('settings')}>{identity.display_name?.slice(0,1)||'T'}</button></div></header>
 <main className="main-content" key={`${tenant}-${page}`}>{page==='overview'?<Overview/>:page==='activities'?<Activities/>:page==='assets'?<Assets/>:page==='cases'?<Cases/>:page==='plans'?<RepaymentPlans/>:page==='payments'?<Payments/>:page==='agents'?<AgentScreen/>:page==='exceptions'?<Exceptions/>:page==='logs'?<Logs/>:page==='strategy'?<Strategy/>:page==='integrations'?<Integrations/>:page==='usage'?<Usage/>:page==='settings'?<Settings/>:<Activities/>}</main></div>
 {activeCase&&<CaseDrawer c={activeCase} tab={caseTab} setTab={setCaseTab} onClose={()=>setCaseId(null)}/>}
 {dialog?.type==='create'&&<CreateWizard defaultPackage={dialog.package} onClose={()=>setDialog(null)}/>}
 {dialog?.type==='policy'&&visiblePackages.length>0&&<PolicyModal packageId={dialog.package||visiblePackages[0].package_id} onClose={()=>setDialog(null)}/>}
 {dialog?.type==='receipt'&&tenant==='TENANT_A'&&<ReceiptModal onClose={()=>setDialog(null)}/>}
 {dialog?.type==='payment'&&dialog.transaction&&<PaymentDetailModal transaction={dialog.transaction} onClose={()=>setDialog(null)}/>}
 {dialog?.type==='reconciliation'&&dialog.receipt&&<ReconciliationModal receipt={dialog.receipt} onClose={()=>setDialog(null)}/>}
 {dialog?.type==='exception'&&<ExceptionModal incidentId={dialog.incidentId} caseId={dialog.caseId} onClose={()=>setDialog(null)}/>}
 {dialog?.type==='plan-create'&&<RepaymentPlanCreateModal onClose={()=>setDialog(null)}/>}
 {dialog?.type==='plan-review'&&activeRepaymentPlan&&<RepaymentPlanReviewModal plan={activeRepaymentPlan} onClose={()=>setDialog(null)}/>}
 {dialog?.type==='import'&&<ImportModal onClose={()=>setDialog(null)}/>}
 {dialog?.type==='help'&&<Modal title="体验一条完整的资产履约流程" subtitle="当前 Provider 与业务数据均为沙箱样本，可随时还原。" onClose={()=>setDialog(null)} footer={<Button variant="primary" onClick={()=>{setDialog(null);navigate('activities')}}>开始体验 <ArrowRight size={16}/></Button>}><ol className="guide"><li><b>完成 AI 与渠道接入</b><p>分别配置 Agent、模型、语音和电话，完成连接、自测与启用。</p></li><li><b>创建履约活动</b><p>选择资产包与目标，由后端重新预检并冻结服务快照。</p></li><li><b>查看 Agent 执行</b><p>查看运行阶段、判断依据和下一步，体验暂停与恢复。</p></li><li><b>核对到账与佣金</b><p>模拟 ¥1,016 到账，观察履约、回款和应计佣金联动。</p></li></ol><div className="notice">API 已连接时配置与门禁写入后端；离线时明确降级为浏览器演示。两种模式都不保存明文凭证，也不会发起真实外呼或支付。</div></Modal>}
 {dialog?.type==='reset'&&<Modal title="还原演示数据" subtitle="将清除本次会话内创建的活动、策略修改和模拟到账。" onClose={()=>setDialog(null)} footer={<><Button onClick={()=>setDialog(null)}>取消</Button><Button variant="primary" onClick={reset}>还原演示</Button></>}><p>还原后回到最初的样本状态。此操作仅影响当前原型。</p></Modal>}
 {searchOpen&&<Modal title="搜索工作空间" onClose={()=>setSearchOpen(false)}><Search value={search} onChange={setSearch} placeholder="输入案件编号、活动名称或功能…"/><div className="command-results">{!search&&<p className="muted small">快速跳转</p>}{Object.entries(titles).filter(([,v])=>!search||v.toLowerCase().includes(search.toLowerCase())).slice(0,search?10:5).map(([id,v])=><button key={id} onClick={()=>{navigate(id);setSearchOpen(false)}}><Command size={17}/><span>{v}</span><ArrowRight size={16}/></button>)}{results.map(c=><button key={c.case_id} onClick={()=>{setSearchOpen(false);openCase(c.case_id)}}><Files size={17}/><span>{c.case_id} · {c.status}</span><small>{c.package_id}</small></button>)}{acts.map(x=><button key={x.id} onClick={()=>{navigate('agents/'+x.id);setSearchOpen(false)}}><Robot size={17}/><span>{x.name}</span><ArrowRight size={16}/></button>)}{search&&!results.length&&!acts.length&&!Object.values(titles).some(v=>v.toLowerCase().includes(search.toLowerCase()))&&<Empty/>}</div><p className="muted small">仅搜索当前组织的数据 · 按 Esc 关闭</p></Modal>}
 <AICopilot/>
 {toast&&<div className="toast" role="status"><CheckCircle size={20} weight="fill"/><span>{toast}</span><IconButton icon={X} label="关闭提示" onClick={()=>setToast('')}/></div>}
 </div></AppContext.Provider>
